import math
import numpy as np

def slippage_bp(qty, adv_shares, sigma, c=1.0):
    """Square-root impact in bp: c * sigma * sqrt(|qty| / adv) * 10,000."""
    return c * sigma * math.sqrt(abs(qty) / adv_shares) * 10_000

def capped_qty(qty, volume, max_participation=0.1):
    """Shares that fill today: at most max_participation of volume,
    as a whole number, with the sign of qty kept."""
    cap = int(max_participation * volume)          # whole shares
    return int(np.sign(qty)) * min(abs(int(qty)), cap)

